    private static RoundDefinition Definition()=>CatalogReader.Exodus("content/exodus/catalog.json",15);
    private static string Json(object? x)=>JsonSerializer.Serialize(x);
    private static readonly System.Collections.Generic.IReadOnlyDictionary<string,double> Speeds=CatalogReader.MonsterSpeeds("content/exodus/catalog.json");
    private static (GameSnapshot State,AdamSession Game) CompletedFourteen()
    {var (state,game)=RoundFourteenTests.CompletedThirteen();game=game.StartNextRound(ExodusContent.Round(14));game.Advance(180);return(state,game);}
    private static (GameSnapshot State,AdamSession Game) Start()
    {var (state,game)=CompletedFourteen();return(state,game.StartNextRound(Definition()));}
    // Existing max equipment, direct timeout and disabled clocks isolate mechanics, not natural play.
    private static (GameSnapshot State,AdamSession Game,BattleWorld World) Boss(bool evolutionOpportunity=false)
    {
        var (state,game)=Start();
        if(evolutionOpportunity)
        {
            var required=new[]{state.Run!.CompletedBoss!,state.Run.CompletedSecondBoss!,state.Run.CompletedThirdBoss!,state.Run.CompletedFourthBoss!}.SelectMany(h=>h.Reward!.Candidates!.Where(c=>c.Id==h.Reward.SelectedId&&c.Kind=="evolution").Select(c=>c.ItemId)).ToArray();
            var removable=state.Run.Forms!.First(x=>!required.Contains(x.Value)).Key;state.Run.Forms!.Remove(removable);game=AdamSession.Resume(state,Definition());
        }
        game.Advance(180);var world=new BattleWorld(game,Speeds,7);world.Advance(2,Vector2.Zero);var s=world.Capture();var actor=s.Enemies.Single(x=>x.Id==1201);actor.X=30;actor.Y=0;
        foreach(var id in game.Inventory.Weapons.Keys)s.Weapons.Add(new BattleWeaponState{WeaponId=id,WeaponForm=game.Inventory.Forms.TryGetValue(id,out var form)?form:null,NextCycle=1000});
        return(state,game,BattleWorld.Restore(game,Speeds,s));
    }
    internal static (GameSnapshot State,AdamSession Game) CompletedFifteen()
    {
        var (state,game,world)=Boss();
        game.Hit(1201,26000);
        world.Advance(0,Vector2.Zero);
        if(!game.CompleteBossSettlement())throw new InvalidOperationException("Expected gold-only R15 completion");
        return (state,game);
    }
    private static void Store(Action<SaveStore> action)
    {var dir=Path.Combine(Path.GetTempPath(),"r15-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{action(new SaveStore(Path.Combine(dir,"save.json")));}finally{Directory.Delete(dir,true);}}
    private static string Histories(GameSnapshot s)=>Json(new{s.Run!.CompletedBoss,s.Run.CompletedSecondBoss,s.Run.CompletedThirdBoss,s.Run.CompletedFourthBoss});
    private static string Identity(GameSnapshot s)=>Json(new{s.Run!.RunId,history=Histories(s),s.Run.Weapons,s.Run.Passives,s.Run.Forms,s.Run.PermanentSnapshot,s.Run.Level,s.Run.Experience,s.Run.ChoiceSerial,s.Run.KillRemainder,s.Profile});
