            var r=BossDefinition.ForRound(15);Check.Equal("defilement_weaver",r.Id);Check.Near(26000,r.MaxHealth);Check.Equal(22,r.Contact);Check.Equal(500,r.KillGold);Check.Near(5,r.AttackPeriod);Check.Near(1,r.TelegraphDuration);Check.Equal(18,r.AttackDamage);Check.True(r.UsesChainProjectiles&&!r.IsChariot);Check.Near(1.35,r.ProjectileSpeed);Check.Near(.16,r.ProjectileRadius);Check.Near(6,r.ProjectileLifetime);Check.Equal(12,r.ProjectileCap);Check.Near(20,r.ProjectileSpreadDegrees);Check.Equal(15,BossDefinition.ForRound(9).AttackDamage);Check.Equal("three-chain-v1:1.35:0.16:6:20:12:",BossDefinition.ChainContract);
