            var (state,game,world)=Boss();world.Advance(4,Vector2.Zero);game.Capture();state.Run!.World=world.Capture();store.Commit(state,0,"warn");var loaded=store.Load()!;var replayGame=AdamSession.Resume(loaded,Definition());var replay=BattleWorld.Restore(replayGame,Speeds,loaded.Run!.World!);world.Advance(1.2,Vector2.UnitY);replay.Advance(1.2,Vector2.UnitY);Check.Equal(Json(world.Capture()),Json(replay.Capture()));Check.Equal(Json(game.Boss),Json(replayGame.Boss));game.Capture();state.Run.World=world.Capture();store.Commit(state,1,"live");loaded=store.Load()!;replayGame=AdamSession.Resume(loaded,Definition());replay=BattleWorld.Restore(replayGame,Speeds,loaded.Run!.World!);world.Advance(.5,Vector2.UnitY);replay.Advance(.5,Vector2.UnitY);Check.Equal(Json(world.Capture()),Json(replay.Capture()));
            var raw=File.ReadAllText(store.Path);File.WriteAllText(store.Path+".bak",raw);foreach(var change in new Action<JsonNode>[] {n=>n["Run"]!["RoundNumber"]=16,n=>n["Run"]!["World"]!["SchemaVersion"]=5,n=>n["Run"]!["Boss"]!["Version"]=4,n=>n["Run"]!["Boss"]!["Reward"]=new JsonObject{["PolicyId"]="future"},n=>n["Run"]!["Boss"]!["ChainDirections"]![0]!["Future"]=1,n=>n["Run"]!["World"]!["HostileProjectiles"]![0]!["Version"]=2,n=>n["Run"]!["CompletedFourthBoss"]!["Future"]=true,n=>n["Run"]!["FutureR16"]=true})
